# Independently authored native observations outside the bounded implicit-chain increment.
# These probes establish GNU R expectations only; some guards may already pass NativR.
# They receive no foundation/recursive compatibility credit and do not inspect callable bodies.
check<-function(name,expr){tryCatch(cat(if(isTRUE(force(expr)))"PASS" else "FAIL",name,"\n"),error=function(e)cat("ERROR",name,conditionMessage(e),"\n"))}
check("forcing-identity: explicit dispatch object retains original argument",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({shared<-new.env(parent=emptyenv());shared$marker<-1L;g<-function(x)UseMethod("g",1L);g.integer<-function(x)list(same=identical(x,shared),marker=x$marker,classes=.Class,method=.Method);g(shared)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(same = TRUE, marker = 1L, classes = c("integer",
"numeric"), method = "g.integer"), warnings = character(0))))
check("forcing-identity: explicit object does not force original argument",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({events<-character();g<-function(x)UseMethod("g",{events<<-c(events,"dispatch");1L});g.integer<-function(x)list(missing=missing(x),events=events,classes=.Class);g(stop("original forced"))}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(missing = FALSE, events = "dispatch", classes = c("integer",
"numeric")), warnings = character(0))))
check("forcing-identity: explicit object preserves named actual positions",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(a,x)UseMethod("g",x);g.integer<-function(a,x)list(a=a,x=x,classes=.Class);g(a="original",x=1L)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(a = "original", x = 1L, classes = c("integer",
"numeric")), warnings = character(0))))
check("forcing-identity: generic default dispatch method default value",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({events<-character();g<-function(x={events<<-c(events,"generic x");1L})UseMethod("g");g.integer<-function(x={events<<-c(events,"method x");2L})list(x=x,events=events,classes=.Class);g()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(error = "no applicable method for 'g' applied to an object of class \"NULL\""),
    warnings = character(0))))
check("forcing-identity: generic local replacement dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x){x<-1L;UseMethod("g")};g.integer<-function(x)list("integer",x,.Class);g.character<-function(x)list("character",x,.Class);g("original")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list("character", "original", "character"), warnings = character(0))))
check("forcing-identity: missing generic input",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g");g.default<-function(x)list(missing=missing(x),classes=.Class,method=.Method);g()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(missing = TRUE, classes = NULL, method = "g.default"),
    warnings = character(0))))
check("forcing-identity: explicit missing generic input",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g");g.name<-function(x)list(missing=missing(x),classes=.Class,method=.Method);g(x=)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(missing = TRUE, classes = "name", method = "g.name"),
    warnings = character(0))))
check("forcing-identity: explicit object missing original argument",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({g<-function(x)UseMethod("g",1L);g.integer<-function(x)list(missing=missing(x),classes=.Class);g()}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(missing = TRUE, classes = c("integer", "numeric"
)), warnings = character(0))))
check("internal-guards: sign ignores implicit methods",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({for(k in c("integer","double","numeric","matrix")){assign(paste0("sign.",k),function(...)stop("member dispatched"));assign(paste0("Math.",k),function(...)stop("Math dispatched"))};x<-1L;a<-sign(x);x<-1.5;b<-sign(x);x<-matrix(1.5,1);c<-sign(x);list(a,b,c)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(1, 1, structure(1, dim = c(1L, 1L))), warnings = character(0))))
check("internal-positive: sign explicit class dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({sign.owned<-function(...)17L;x<-structure(1,class="owned");sign(x)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = 17L, warnings = character(0))))
check("internal-guards: signif ignores implicit methods",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({for(k in c("integer","double","numeric","matrix")){assign(paste0("signif.",k),function(...)stop("member dispatched"));assign(paste0("Math.",k),function(...)stop("Math dispatched"))};x<-1L;a<-signif(x,2L);x<-1.5;b<-signif(x,2L);x<-matrix(1.5,1);c<-signif(x,2L);list(a,b,c)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(1, 1.5, structure(1.5, dim = c(1L, 1L))), warnings = character(0))))
check("internal-positive: signif explicit class dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({signif.owned<-function(...)17L;x<-structure(1,class="owned");signif(x,2L)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = 17L, warnings = character(0))))
check("internal-guards: ceiling ignores implicit methods",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({for(k in c("integer","double","numeric","matrix")){assign(paste0("ceiling.",k),function(...)stop("member dispatched"));assign(paste0("Math.",k),function(...)stop("Math dispatched"))};x<-1L;a<-ceiling(x);x<-1.5;b<-ceiling(x);x<-matrix(1.5,1);c<-ceiling(x);list(a,b,c)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(1, 2, structure(2, dim = c(1L, 1L))), warnings = character(0))))
check("internal-positive: ceiling explicit class dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({ceiling.owned<-function(...)17L;x<-structure(1,class="owned");ceiling(x)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = 17L, warnings = character(0))))
check("internal-guards: trunc ignores implicit methods",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({for(k in c("integer","double","numeric","matrix")){assign(paste0("trunc.",k),function(...)stop("member dispatched"));assign(paste0("Math.",k),function(...)stop("Math dispatched"))};x<-1L;a<-trunc(x);x<-1.5;b<-trunc(x);x<-matrix(1.5,1);c<-trunc(x);list(a,b,c)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(1, 1, structure(1, dim = c(1L, 1L))), warnings = character(0))))
check("internal-positive: trunc explicit class dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({trunc.owned<-function(...)17L;x<-structure(1,class="owned");trunc(x)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = 17L, warnings = character(0))))
check("internal-guards: direct subset ignores implicit methods",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({`[[.integer`<-function(...)stop("integer dispatched");`[[.numeric`<-function(...)stop("numeric dispatched");`[[.matrix`<-function(...)stop("matrix dispatched");list(`[[`(1L,1L),`[[`(1,1L),`[[`(matrix(1L,1),1L))}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(1L, 1, 1L), warnings = character(0))))
check("internal-positive: direct subset explicit class dispatch",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({`[[.owned`<-function(...)17L;`[[`(structure(1,class="owned"),1L)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = 17L, warnings = character(0))))
check("internal-guards: shQuote character conversion implicit methods",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({as.character.integer<-function(x,...)"dispatched integer";as.character.numeric<-function(x,...)"dispatched numeric";list(shQuote(1L,type="sh"),shQuote(1,type="sh"))}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list("'1'", "'1'"), warnings = character(0))))
check("internal-positive: shQuote character conversion explicit class",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({as.character.owned<-function(x,...)"owned value";shQuote(structure(1,class="owned"),type="sh")}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = "'1'", warnings = character(0))))
check("explicit-unusual-precedence: language",identical(local({warnings<-character();value<-tryCatch(withCallingHandlers(local({x<-quote(f(x));attr(x,"class")<-c("owned","second");g<-function(x)UseMethod("g");g.owned<-function(x)list(first=list(.Class,.Method,typeof(x)),tail=NextMethod());g.second<-function(x)list(.Class,.Method,typeof(x),class(x));g.default<-function(x)stop("unexpected default");g(x)}),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart("muffleWarning")}),error=function(e)list(error=conditionMessage(e)));list(value=value,warnings=warnings)}),list(value = list(first = list(c("owned", "second"), "g.owned",
    "language"), tail = list(structure("second", previous = c("owned",
"second")), "g.second", "language", c("owned", "second"))), warnings = character(0))))
